import os, requests, json, urllib.parse
url=os.environ['GALAXY_URL'].rstrip('/')
key=open(os.environ['GALAXY_API_KEY_FILE']).read().strip(); headers={'x-api-key':key}
hid='bbd44e69cb8906b553306e5b82096017'
for tid in ['toolshed.g2.bx.psu.edu/repos/iuc/minimap2/minimap2/2.31+galaxy1','toolshed.g2.bx.psu.edu/repos/devteam/bowtie2/bowtie2/2.5.5+galaxy0']:
    data=requests.get(url+'/api/tools/'+urllib.parse.quote(tid, safe='')+'/build', params={'history_id':hid}, headers=headers, timeout=60).json()
    print('\\nTOOL',data.get('name'),data.get('id'))
    print('state_inputs', json.dumps(data.get('state_inputs'), indent=2)[:5000])
    def summarize(inp, indent=0):
        pref=' '*indent; print(pref+inp.get('model_class','?'), inp.get('name'), inp.get('type'), 'value='+repr(inp.get('value',None))[:60])
        if inp.get('type')=='select':
            opts=inp.get('options') or []
            hits=[o for o in opts if any(s in str(o).lower() for s in ['hg38','grch38','homo sapiens'])]
            if hits: print(pref+' hits',hits[:10])
        for child in inp.get('cases',[]) or []:
            print(pref+' case', child.get('value'))
            for ci in child.get('inputs',[]) or []: summarize(ci, indent+2)
        for ci in inp.get('inputs',[]) or []: summarize(ci, indent+2)
    for inp in data['inputs'][:10]: summarize(inp)
PY"

